import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_tseitin_formula(n):
        variables = [f'x{i}' for i in range(1, n+1)]
        clauses = []
        for x in variables:
            clauses.append([x])
        for i in range(1, n):
            clauses.append([f'~{variables[i-1]}', f'{variables[i]}'])
        return clauses

    def resolution(clauses):
        new_clauses = set()
        while True:
            new_clause = None
            for c1 in clauses:
                for c2 in clauses:
                    if len(c1) > 1 and len(c2) > 1 and any(x == f'~{y}' for x, y in zip(c1, c2)):
                        new_clause = [x for x in c1 + c2 if x != x and f'~{x}' not in c2]
                        break
                if new_clause:
                    break
            if not new_clause:
                return len(clauses)
            clauses.add(tuple(sorted(new_clause)))

    def topological_entropy(n):
        return n * math.log(n, 2)

    results = []
    for n in [5, 10, 15, 20, 30, 40]:
